    function classifyCustomEffect(family, name, slug) {
      if (family === "other" || CUSTOM_EFFECT_FAMILY_RULES.some(([id]) => id === family)) return family;
      const label = `${name} ${slug}`.toLowerCase();
      return CUSTOM_EFFECT_FAMILY_RULES.find(([, pattern]) => pattern.test(label))?.[0] ?? "other";
    }

