    // 自由定制动效引擎（Canvas 2D + WebGL GLSL 双模式，含离屏校验与熔断护栏）
    // =========================================================================
    const DCS_EFFECT_FORMAT = "dsh-claude-slider-effect";
    const CUSTOM_EFFECTS_STORAGE_KEY = "dsh-claude-slider.custom-effects.v1";
    const MAX_CUSTOM_EFFECTS = 24;
    const MAX_CUSTOM_EFFECT_CODE_BYTES = 65536;

    const CUSTOM_EFFECT_HELPERS = {
      ease(start, end, v) {
        const t = Math.min(1, Math.max(0, (v - start) / (end - start || 1e-6)));
        return t * t * (3 - 2 * t);
      },
      dot(ctx, x, y, r, color) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.arc(x, y, r, 0, Math.PI * 2);
        ctx.fill();
      },
      ellipseGlow(ctx, cx, cy, rx, ry, angle, stops) {
        ctx.save();
        ctx.translate(cx, cy);
        if (angle) ctx.rotate(angle);
        ctx.scale(rx / 32, ry / 32);
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, 32);
        for (let i = 0; i < stops.length; i++) grad.addColorStop(stops[i][0], stops[i][1]);
        ctx.fillStyle = grad;
        ctx.fillRect(-32, -32, 64, 64);
        ctx.restore();
      },
      rand(seed) {
        // 不传 seed 时直接返回 [0,1) 随机数（兼容把 h.rand() 当 Math.random() 调用的自定义脚本）；
        // 传 seed 时返回确定性伪随机生成器 () => [0,1)
        if (seed === void 0) return Math.random();
        let a = (seed >>> 0) || 1;
        return () => {
          a = (a + 0x6D2B79F5) | 0;
          let t = Math.imul(a ^ (a >>> 15), 1 | a);
          t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
          return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
      },
      createCanvas(w, h) {
        const c = document.createElement("canvas");
        c.width = Math.max(1, Math.min(1024, Math.round(w)));
        c.height = Math.max(1, Math.min(512, Math.round(h)));
        return c;
      }
    };

    const DCS_GLSL_VERT = "attribute vec2 a_pos; varying vec2 v_uv; void main(){ v_uv = a_pos * 0.5 + 0.5; gl_Position = vec4(a_pos, 0.0, 1.0); }";
    const DCS_GLSL_HEADER = [
      "precision mediump float;",
      "varying vec2 v_uv;",
      "uniform vec2 u_resolution;",
      "uniform float u_time;",
      "uniform float u_progress;",
      "uniform float u_high;",
      "uniform float u_max;",
      "uniform float u_burst;",
      "uniform float u_dark;",
      "uniform float u_brightness;",
      "uniform vec2 u_pointer;",
      "uniform vec3 u_accent;",
      "uniform vec3 u_accent_light;",
      "uniform vec3 u_accent_deep;",
      "uniform vec3 u_monet_sec;",
      "uniform vec3 u_monet_ter;"
    ].join("\n");

    const CUSTOM_EFFECT_AI_PROMPT = [
      "你现在是 DSH Claude Slider 滑块动效设计师。请帮我生成一个可直接导入的 .dcs-effect.json 动效包。",
      "",
      "【输出格式】请只输出一个合法 JSON 对象（不要多余解释）：",
      "{",
      '  "format": "dsh-claude-slider-effect",',
      '  "version": 1,',
      '  "id": "custom:英文短名",',
      '  "name": "中文短名(4-6字)",',
      '  "author": "AI",',
      '  "mode": "canvas2d 或 glsl",',
      '  "clip": "progress 或 track",',
      '  "colorMode": "theme 或 tinted 或 fixed",',
      '  "code": "完整脚本字符串"',
      "}",
      "",
      "【接口规范（请严格遵守单位，避免动效卡死或变纯色）】",
      '1. mode="canvas2d"：code 必须 return { init(api) { /* 可选预绘缓存 */ }, draw(ctx, s) { ... } }。逻辑高度固定 32px，宽 s.width，进度末端 s.end。',
      "   - 时间单位：s.time 是秒级连续动画时钟，s.dt 是以 60 FPS 归一的动画步长。两者均已应用流速。60 FPS、1× 时 s.dt 约为 1，静止时为 0；积分时使用 s.dt / 60 换算秒。",
      "   - 调色盘用法：s.pal.main(alpha) / s.pal.light(alpha) / s.pal.deep(alpha) / s.pal.secondary(alpha) 都是函数（传 0~1 透明度），s.pal.hex 是十六进制字符串；s.monet 含 primary/secondary/tertiary 同结构。",
      "   - 持续运动原则：严禁做纯重力沉底且速度衰减归零的死粒子！必须用平流循环、波浪悬浮、涡流扬起或重生机制保证画面全程肉眼可见地流畅流动。",
      "   - 其他字段：ratio(0-1), high(0-1), max(0-1), burst(1->0), dark(bool), brightness, velocity, pointer({x,y,inside}), h(dot/ease/ellipseGlow/rand[无参返回0-1，传seed返回生成器]/createCanvas), state。",
      '2. mode="glsl"：code 只写 main() 及辅助函数（已注入 u_resolution, u_time, u_progress, u_high, u_max, u_burst, u_dark, u_brightness, u_pointer, u_accent, u_accent_light, u_accent_deep, u_monet_sec, u_monet_ter 与 v_uv）。',
      "3. 深浅主题兼容：浅色模式（s.dark === false）必须保持清晰轮廓与饱和对比度；Low 沉稳克制、High 舒展流动、Max 释放爆发。",
      "",
      "【我想要的动效创意】",
      "（在这里写下你的创意，例如：赛博暴雨网格 / 黑洞熔岩 / 水墨游鱼 / 极简丝光）"
    ].join("\n");

    function buildCustomMonetContext(primaryHex, secHex, terHex, brightness) {
      const primary = getColorPalette(primaryHex, brightness);
      const secondary = secHex ? getColorPalette(secHex, brightness) : primary;
      const tertiary = terHex ? getColorPalette(terHex, brightness) : secondary;
      return {
        enabled: Boolean(secHex || terHex),
        primary,
        secondary,
        tertiary,
        swatches: [primary.hex, secondary.hex, tertiary.hex]
      };
    }

    function normalizeCustomEffectPackage(raw) {
      if (!raw || typeof raw !== "object") throw new Error("动效包必须是 JSON 对象");
      if (raw.format && raw.format !== DCS_EFFECT_FORMAT) {
        throw new Error(`不支持的格式标识: ${raw.format}`);
      }
      const name = String(raw.name || "").trim().slice(0, 24);
      if (!name) throw new Error("缺少动效名称 (name)");
      const slug = String(raw.id || name)
        .replace(/^custom:/, "")
        .toLowerCase()
        .replace(/[^a-z0-9_-]+/g, "_")
        .replace(/^_+|_+$/g, "") || ("fx_" + Date.now().toString(36));
      const mode = raw.mode === "glsl" ? "glsl" : "canvas2d";
      const clip = raw.clip === "track" ? "track" : "progress";
      const colorMode = ["theme", "tinted", "fixed"].includes(raw.colorMode) ? raw.colorMode : "theme";
      const code = String(raw.code || "");
      if (!code.trim()) throw new Error("缺少渲染代码 (code)");
      if (code.length > MAX_CUSTOM_EFFECT_CODE_BYTES) throw new Error("代码体积超过 64KB 限制");
      return {
        format: DCS_EFFECT_FORMAT,
        version: 1,
        id: `custom:${slug}`,
        name,
        family: classifyCustomEffect(raw.family, name, slug),
        author: String(raw.author || "custom").slice(0, 32),
        description: String(raw.description || "").slice(0, 140),
        mode,
        clip,
        colorMode,
        code
      };
    }

    function createCustomGlslProgram(gl, fragBody) {
      const compile = (type, src) => {
        const sh = gl.createShader(type);
        gl.shaderSource(sh, src);
        gl.compileShader(sh);
        if (!gl.getShaderParameter(sh, gl["COMPILE_STATUS"])) {
          const log = gl.getShaderInfoLog(sh) || "GLSL 编译失败";
          gl.deleteShader(sh);
          throw new Error(log.trim());
        }
        return sh;
      };
      const vs = compile(gl["VERTEX_SHADER"], DCS_GLSL_VERT);
      const fs = compile(gl["FRAGMENT_SHADER"], DCS_GLSL_HEADER + "\n" + fragBody);
      const prog = gl.createProgram();
      gl.attachShader(prog, vs);
      gl.attachShader(prog, fs);
      gl.linkProgram(prog);
      gl.deleteShader(vs);
      gl.deleteShader(fs);
      if (!gl.getProgramParameter(prog, gl["LINK_STATUS"])) {
        const log = gl.getProgramInfoLog(prog) || "GLSL 链接失败";
        gl.deleteProgram(prog);
        throw new Error(log.trim());
      }
      const buf = gl.createBuffer();
      gl.bindBuffer(gl["ARRAY_BUFFER"], buf);
      gl.bufferData(gl["ARRAY_BUFFER"], new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl["STATIC_DRAW"]);
      const loc = gl.getAttribLocation(prog, "a_pos");
      gl.enableVertexAttribArray(loc);
      gl.vertexAttribPointer(loc, 2, gl["FLOAT"], false, 0, 0);
      const uniforms = {};
      [
        "u_resolution", "u_time", "u_progress", "u_high", "u_max", "u_burst", "u_dark", "u_brightness",
        "u_pointer", "u_accent", "u_accent_light", "u_accent_deep", "u_monet_sec", "u_monet_ter"
      ].forEach((k) => { uniforms[k] = gl.getUniformLocation(prog, k); });
      return {
        prog,
        buf,
        uniforms,
        dispose() {
          try { gl.deleteBuffer(buf); gl.deleteProgram(prog); } catch (_) {}
        }
      };
    }

    const customEffectCompileCache = new Map();
    const customEffectListeners = new Set();

    function loadCustomEffectsList() {
      if (typeof window === "undefined") return [];
      try {
        const raw = window.localStorage.getItem(CUSTOM_EFFECTS_STORAGE_KEY);
        if (!raw) return [];
        const parsed = JSON.parse(raw);
        if (!Array.isArray(parsed)) return [];
        const out = [];
        const seen = new Set();
        for (let i = 0; i < parsed.length && out.length < MAX_CUSTOM_EFFECTS; i++) {
          try {
            const norm = normalizeCustomEffectPackage(parsed[i]);
            if (!seen.has(norm.id)) {
              seen.add(norm.id);
              out.push(norm);
            }
          } catch (_) {}
        }
        return out;
      } catch (_) {
        return [];
      }
    }

    let customEffectsCache = loadCustomEffectsList();

    function notifyCustomEffectsChanged() {
      customEffectListeners.forEach((fn) => {
        try { fn(customEffectsCache); } catch (_) {}
      });
    }

    function saveCustomEffectsList(nextList) {
      customEffectsCache = nextList.slice(0, MAX_CUSTOM_EFFECTS);
      try {
        window.localStorage.setItem(CUSTOM_EFFECTS_STORAGE_KEY, JSON.stringify(customEffectsCache));
      } catch (_) {}
      notifyCustomEffectsChanged();
    }

    function getCustomEffectById(id) {
      if (!id || typeof id !== "string") return null;
      return customEffectsCache.find((item) => item.id === id) || null;
    }

    function compileAndValidateCustomEffect(rawPkg) {
      const norm = normalizeCustomEffectPackage(rawPkg);
      const testPal = getColorPalette("#EF4444", 1.0);
      const testMonet = buildCustomMonetContext("#EF4444", "#F59E0B", "#FDE047", 1.0);

      if (norm.mode === "canvas2d") {
        const factory = new Function("api", norm.code);
        const mod = factory({ h: CUSTOM_EFFECT_HELPERS });
        if (!mod || typeof mod.draw !== "function") {
          throw new Error("Canvas 2D 代码必须 return { draw(ctx, s) { ... } }");
        }
        if (typeof document !== "undefined") {
          const testCanvas = CUSTOM_EFFECT_HELPERS.createCanvas(300, 32);
          const tCtx = testCanvas.getContext("2d");
          if (tCtx) {
            const st = typeof mod.init === "function"
              ? (mod.init({ h: CUSTOM_EFFECT_HELPERS, pal: testPal, monet: testMonet, dark: true, brightness: 1.0 }) || {})
              : {};
            const t0 = performance.now();
            for (let f = 0; f < 2; f++) {
              mod.draw(tCtx, {
                width: 300, end: 210, height: 32,
                time: 1.2 + f * 0.05, dt: 1, ratio: 0.7, high: 1, max: f, burst: f * 0.5,
                pal: testPal, monet: testMonet, dark: true, brightness: 1.0,
                tilt: 0, velocity: 0, dragging: false,
                pointer: { x: 150, y: 16, inside: false },
                h: CUSTOM_EFFECT_HELPERS, state: st
              });
            }
            const avgMs = (performance.now() - t0) / 2;
            if (avgMs > 60) throw new Error(`离屏试跑耗时过高 (${avgMs.toFixed(1)}ms > 60ms)`);
          }
        }
        return { pkg: norm, factory };
      }

      if (typeof document !== "undefined") {
        const glCanvas = CUSTOM_EFFECT_HELPERS.createCanvas(180, 32);
        const gl = glCanvas.getContext("webgl", { alpha: true, premultipliedAlpha: false });
        if (!gl) throw new Error("当前环境不支持 WebGL 着色器模式");
        const compiled = createCustomGlslProgram(gl, norm.code);
        gl.viewport(0, 0, 180, 32);
        gl.useProgram(compiled.prog);
        gl.uniform2f(compiled.uniforms.u_resolution, 180, 32);
        gl.uniform1f(compiled.uniforms.u_time, 1.2);
        gl.uniform1f(compiled.uniforms.u_progress, 0.7);
        gl.uniform3fv(compiled.uniforms.u_accent, testPal.rgb01);
        gl.drawArrays(gl["TRIANGLE_STRIP"], 0, 4);
        compiled.dispose();
      }
      return { pkg: norm, factory: null };
    }

    function upsertCustomEffectPackage(rawPkg) {
      const compiled = compileAndValidateCustomEffect(rawPkg);
      const norm = compiled.pkg;
      customEffectCompileCache.set(norm.id, { sig: `${norm.mode}|${norm.clip}|${norm.colorMode}|${norm.code}`, compiled });
      const next = customEffectsCache.filter((item) => item.id !== norm.id);
      next.unshift(norm);
      saveCustomEffectsList(next);
      return norm;
    }

    function removeCustomEffectById(id) {
      customEffectCompileCache.delete(id);
      const next = customEffectsCache.filter((item) => item.id !== id);
      saveCustomEffectsList(next);
    }

    const customCanvasRunners = new WeakMap();

    function disposeCustomEffectRunner(canvas) {
      const runner = customCanvasRunners.get(canvas);
      if (!runner) return;
      if (runner.glProg) {
        runner.glProg.dispose();
        runner.glProg = null;
      }
      if (runner.glCanvas && runner.glCanvas.parentNode) {
        runner.glCanvas.parentNode.removeChild(runner.glCanvas);
      }
      customCanvasRunners.delete(canvas);
    }

    function hideCustomGlOverlay(canvas) {
      const runner = customCanvasRunners.get(canvas);
      if (runner && runner.glCanvas && runner.glCanvas.style.display !== "none") {
        runner.glCanvas.style.display = "none";
      }
    }

    function ensureCustomGlOverlay(canvas, runner) {
      if (!runner.glCanvas) {
        const gc = document.createElement("canvas");
        gc.className = "dcs-effect-gl-canvas";
        gc.style.cssText = "position:absolute;top:0;left:0;width:100%;height:100%;pointer-events:none;border-radius:15px;display:none;";
        runner.glCanvas = gc;
      }
      if (canvas && canvas.parentElement && runner.glCanvas.parentElement !== canvas.parentElement) {
        canvas.parentElement.insertBefore(runner.glCanvas, canvas.nextSibling);
      }
      return runner.glCanvas;
    }

    function prepareCustomCanvas2d(runner, width, height) {
      const ctx = runner.ctx2d ??= document.createElement("canvas").getContext("2d");
      const canvas = ctx.canvas;
      if (canvas.width !== width || canvas.height !== height) {
        canvas.width = width;
        canvas.height = height;
      } else if (typeof ctx.reset === "function") {
        ctx.reset();
      } else {
        canvas.width = width;
      }
      return ctx;
    }

    function drawCustomEffectFallback(ctx, { end, height, pal, dark }) {
      ctx.save();
      ctx.globalCompositeOperation = "source-over";
      ctx.globalAlpha = 1;
      ctx.fillStyle = pal.deep(dark ? 0.55 : 0.35);
      ctx.fillRect(0, 0, end, height);
      ctx.restore();
    }

    function compositeCustomEffect(ctx, canvas, width, height, opacity = 1) {
      if (width <= 0) return;
      ctx.save();
      try {
        ctx.globalCompositeOperation = "source-over";
        ctx.globalAlpha = opacity;
        ctx.drawImage(canvas, 0, 0, width, height, 0, 0, width, height);
      } finally {
        ctx.restore();
      }
    }

    function drawCustomEffectOnCanvas(canvas, ctx, pkg, frame) {
      let runner = customCanvasRunners.get(canvas);
      if (!runner) {
        runner = {
          pkg: null,
          mod: null,
          state: null,
          ctx2d: null,
          colorSig: "",
          glCanvas: null,
          gl: null,
          glProg: null,
          errCount: 0,
          tripped: false,
          lastError: ""
        };
        customCanvasRunners.set(canvas, runner);
      }
      if (runner.pkg !== pkg) {
        hideCustomGlOverlay(canvas);
        if (runner.glProg) {
          runner.glProg.dispose();
          runner.glProg = null;
        }
        runner.pkg = pkg;
        runner.mod = null;
        runner.state = null;
        runner.colorSig = "";
        runner.errCount = 0;
        runner.tripped = false;
        runner.lastError = "";
        try {
          const sig = `${pkg.mode}|${pkg.clip}|${pkg.colorMode}|${pkg.code}`;
          let cached = customEffectCompileCache.get(pkg.id);
          if (!cached || cached.sig !== sig) {
            const compiled = compileAndValidateCustomEffect(pkg);
            cached = { sig, compiled };
            customEffectCompileCache.set(pkg.id, cached);
          }
          if (pkg.mode === "canvas2d") {
            runner.mod = cached.compiled.factory({ h: CUSTOM_EFFECT_HELPERS });
          } else {
            const gc = ensureCustomGlOverlay(canvas, runner);
            runner.gl = gc.getContext("webgl", {
              alpha: true,
              premultipliedAlpha: true,
              antialias: false,
              depth: false,
              stencil: false,
              powerPreference: "high-performance"
            });
            if (runner.gl) {
              runner.glProg = createCustomGlslProgram(runner.gl, pkg.code);
            } else {
              throw new Error("WebGL 上下文不可用");
            }
          }
        } catch (e) {
          runner.tripped = true;
          runner.lastError = e?.message || String(e);
        }
      }

      const { width, end, height, time, dt, ratio, high, max, burst, pal, monet, dark, brightness, tilt, velocity, dragging, pointer } = frame;
      if (runner.tripped) {
        drawCustomEffectFallback(ctx, frame);
        return;
      }

      const scale = height / 32;
      const sceneW = width / scale;
      const sceneEnd = end / scale;
      const clipWidth = pkg.clip === "track" ? width : Math.min(width, Math.max(0, end));

      try {
        const colorSig = `${pal.hex}|${monet.secondary.hex}|${monet.tertiary.hex}|${dark ? 1 : 0}`;
        if (pkg.mode === "canvas2d" && runner.mod) {
          if (!runner.state || (pkg.colorMode !== "fixed" && runner.colorSig !== colorSig)) {
            runner.state = typeof runner.mod.init === "function"
              ? (runner.mod.init({ h: CUSTOM_EFFECT_HELPERS, pal, monet, dark, brightness }) || {})
              : {};
            runner.colorSig = colorSig;
          }
          // 脚本在独立画布绘制，变换、裁切和状态栈不会污染轨道。
          const fxCtx = prepareCustomCanvas2d(runner, width, height);
          fxCtx.setTransform(scale, 0, 0, scale, 0, 0);
          fxCtx.globalAlpha = Math.min(1, 0.38 + brightness * 0.58);
          runner.mod.draw(fxCtx, {
            width: sceneW, end: sceneEnd, height: 32,
            time, dt, ratio, high, max, burst,
            pal, monet, dark, brightness, tilt, velocity, dragging,
            pointer: { x: (pointer?.x || 0) / scale, y: (pointer?.y || 0) / scale, inside: Boolean(pointer?.inside) },
            h: CUSTOM_EFFECT_HELPERS,
            state: runner.state
          });
          compositeCustomEffect(ctx, fxCtx.canvas, clipWidth, height);
        } else if (pkg.mode === "glsl" && runner.gl && runner.glProg) {
          const gc = ensureCustomGlOverlay(canvas, runner);
          if (gc.width !== width || gc.height !== height) {
            gc.width = width;
            gc.height = height;
          }
          const gl = runner.gl;
          const u = runner.glProg.uniforms;
          gl.viewport(0, 0, width, height);
          gl.clearColor(0, 0, 0, 0);
          gl.clear(gl["COLOR_BUFFER_BIT"]);
          gl.useProgram(runner.glProg.prog);
          gl.uniform2f(u.u_resolution, width, height);
          gl.uniform1f(u.u_time, time);
          gl.uniform1f(u.u_progress, ratio);
          gl.uniform1f(u.u_high, high);
          gl.uniform1f(u.u_max, max);
          gl.uniform1f(u.u_burst, burst);
          gl.uniform1f(u.u_dark, dark ? 1.0 : 0.0);
          gl.uniform1f(u.u_brightness, brightness);
          gl.uniform2f(u.u_pointer, (pointer?.x || 0) / Math.max(1, width), 1.0 - (pointer?.y || 0) / Math.max(1, height));
          gl.uniform3fv(u.u_accent, pal.rgb01);
          gl.uniform3fv(u.u_accent_light, pal.lightRgb01);
          gl.uniform3fv(u.u_accent_deep, pal.deepRgb01);
          gl.uniform3fv(u.u_monet_sec, monet.secondary.rgb01);
          gl.uniform3fv(u.u_monet_ter, monet.tertiary.rgb01);
          gl.drawArrays(gl["TRIANGLE_STRIP"], 0, 4);

          if (gc.parentElement === canvas.parentElement) {
            // 直接合成硬件 WebGL 画布层，跳过每帧 drawImage GPU->2D 拷贝
            const rightPct = pkg.clip === "track" ? 0 : Math.max(0, 100 - (end / Math.max(1, width)) * 100);
            gc.style.display = "block";
            gc.style.opacity = String(Math.min(1, 0.38 + brightness * 0.58));
            gc.style.clipPath = rightPct > 0.05 ? `inset(0 ${rightPct.toFixed(2)}% 0 0)` : "none";
          } else {
            compositeCustomEffect(ctx, gc, clipWidth, height, Math.min(1, 0.38 + brightness * 0.58));
          }
        }
        runner.errCount = 0;
      } catch (e) {
        runner.errCount++;
        runner.lastError = e?.message || String(e);
        if (runner.errCount >= 3) runner.tripped = true;
        hideCustomGlOverlay(canvas);
        drawCustomEffectFallback(ctx, frame);
      }
    }

    function resolveEffect(id) {
      if (!id) return "liquid_mercury";
      if (EFFECT_MODES.some((m) => m.id === id)) return id;
      if (getCustomEffectById(id)) return id;
      return Object.hasOwn(LEGACY_EFFECT_MAP, id) ? LEGACY_EFFECT_MAP[id] : "liquid_mercury";
    }

    // 以 32px 为绘制高度，在普通窗口和高像素密度屏幕上使用同一构图。
    const sceneSkies = {
      gpt_starlight: [[0, "#3c147d"], [0.19, "#5420ac"], [0.35, "#732bdd"], [0.53, "#8832e5"],
        [0.70, "#9b45ee"], [0.88, "#b174f4"], [1, "#bf84f6"]],
      claude_mosaic: [[0, "#a297cd"], [0.20, "#e4dcf4"], [0.78, "#ded3f3"], [1, "#b2a4d8"]]
    };
    const sceneGradients = new WeakMap();
    const glassOutlines = [
      [0, -1.2, 1.0, 0.70, -0.82, 0.96],
      [0.12, -1.27, 0.82, -0.06, -0.04, 1.28, -0.83, 0.14],
      [-0.74, -0.76, 0.52, -1.02, 1.02, -0.26, 0.58, 0.91, -0.95, 0.52]
    ];
    let glassPaths;

    function getGlassPaths() {
      if (!glassPaths) {
        glassPaths = glassOutlines.map((points) => {
          const outline = new Path2D();
          outline.moveTo(points[0], points[1]);
          const facets = [];
          for (let corner = 0; corner < points.length; corner += 2) {
            const next = (corner + 2) % points.length;
            const facet = new Path2D();
            facet.moveTo(-0.13, 0.1);
            facet.lineTo(points[corner], points[corner + 1]);
            facet.lineTo(points[next], points[next + 1]);
            facet.closePath();
            facets.push(facet);
            if (corner > 0) outline.lineTo(points[corner], points[corner + 1]);
          }
          outline.closePath();
          return { outline, facets };
        });
      }
      return glassPaths;
    }

    function sceneDot(ctx, x, y, radius, color) {
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.arc(x, y, radius, 0, Math.PI * 2);
      ctx.fill();
    }

    function sliderIdleSpeed(ratio, isDragging, idleElapsed) {
      if (isDragging) return 1;
      // 低档也要看得出流动，静置时再随档位降低少许。
      return idleElapsed > 1500 ? 0.58 + 0.30 * ratio : 0.82 + 0.18 * ratio;
    }

    function createMercuryMotion() {
      return { previousRatio: 0, wasDragging: false, tilt: 0, velocity: 0 };
    }

    function stepMercuryTilt(motion, ratio, dragging, seconds, enabled) {
      const canMeasureDrag = enabled && dragging && motion.wasDragging;
      const dragSpeed = canMeasureDrag ? (ratio - motion.previousRatio) / seconds : 0;
      motion.previousRatio = ratio;
      motion.wasDragging = enabled && dragging;
      if (!enabled || (dragSpeed === 0 && Math.abs(motion.tilt) < 0.025 && Math.abs(motion.velocity) < 0.2)) {
        motion.tilt = 0;
        motion.velocity = 0;
        return 0;
      }

      // 拖动速度给液面一个有界的倾斜目标，松手后弹簧回到水平。
      const target = Math.max(-8, Math.min(8, dragSpeed * 6.5));
      const damping = 3.4;
      const frequency = 14;
      const offset = motion.tilt - target;
      const sineWeight = (motion.velocity + damping * offset) / frequency;
      const phase = frequency * seconds;
      const sine = Math.sin(phase);
      const cosine = Math.cos(phase);
      const decay = Math.exp(-damping * seconds);
      const swing = offset * cosine + sineWeight * sine;
      motion.tilt = target + swing * decay;
      motion.velocity = (frequency * (sineWeight * cosine - offset * sine) - damping * swing) * decay;
      return Math.max(-12, Math.min(12, motion.tilt));
    }

    function drawGlassMercury(ctx, end, time, high, max, pal, tilt) {
      const count = Math.round(7 + high * 3 + max * 5);
      const span = end + 14;
      const paths = getGlassPaths();
      const tint = pal.light(0.84);
      for (let i = 0; i < count; i++) {
        const phase = (i * 0.618034 + 0.14) % 1;
        const drift = time * (6.5 + i % 4 * 1.5) / span;
        const x = (((phase - drift) % 1 + 1) % 1) * span - 7;
        const slosh = tilt * (x - end * 0.5) / Math.max(end, 32);
        const y = 7 + ((i * 43) % 17) + Math.sin(time * 0.53 + i * 2.21) * 2.0 + slosh * 0.85;
        const size = 2.6 + (i % 4) * 0.85 + 0.55 * max;
        const turn = i * 1.71 + time * (i % 2 === 0 ? 0.76 : -0.62);
        const { outline, facets } = paths[i % paths.length];
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(i * 0.73 + time * 0.27 + slosh * 0.045);
        ctx.scale((Math.cos(turn) * 0.78 + 0.20) * size, size);
        for (let face = 0; face < facets.length; face++) {
          ctx.fillStyle = face === 0 ? "rgba(249, 255, 255, 0.92)"
            : face === 1 ? tint : face === 2 ? "rgba(21, 48, 74, 0.68)" : "rgba(140, 199, 223, 0.79)";
          ctx.fill(facets[face]);
        }
        ctx.lineWidth = 0.68 / size;
        ctx.strokeStyle = "rgba(239, 254, 255, 0.79)";
        ctx.stroke(outline);
        ctx.restore();

        const gleam = Math.max(0, Math.cos(turn + 0.54)) ** 12;
        if (max * gleam > 0.07) {
          ctx.fillStyle = `rgba(242, 253, 255, ${0.7 * max * gleam})`;
          ctx.fillRect(x - 3, y - 0.4, 6, 0.8);
          ctx.fillRect(x - 0.4, y - 2.5, 0.8, 5);
        }
      }
    }

    function sceneEase(start, end, value) {
      const t = Math.min(1, Math.max(0, (value - start) / (end - start)));
      return t * t * (3 - 2 * t);
    }

    let starGlowTexture;

    function getStarGlowTexture() {
      if (starGlowTexture) return starGlowTexture;
      const sprite = document.createElement("canvas");
      sprite.width = sprite.height = 32;
      const ctx = sprite.getContext("2d");
      const glow = ctx.createRadialGradient(16, 16, 0, 16, 16, 16);
      glow.addColorStop(0, "rgba(255, 244, 255, 0.78)");
      glow.addColorStop(0.34, "rgba(240, 215, 255, 0.27)");
      glow.addColorStop(1, "rgba(230, 185, 255, 0)");
      ctx.fillStyle = glow;
      ctx.fillRect(0, 0, 32, 32);
      starGlowTexture = sprite;
      return sprite;
    }

    function drawGptStarlight(ctx, end, time, high, max, burst) {
      const span = end + 12;
      const glow = getStarGlowTexture();
      const count = Math.round(8 + 8 * high + 8 * max);
      for (let i = 0; i < count; i++) {
        const speed = 11 + (i % 6) * 2.5 + 4.2 * max;
        const x = ((i * 71 % 139) / 139 * span + time * speed) % span - 6;
        const y = 3.6 + i * 17 % 25 + 0.63 * Math.sin(time * 1.05 + i);
        const shimmer = 0.5 + 0.5 * Math.sin(time * 1.6 + i * 2.41);
        const front = sceneEase(0.54, 0.94, x / end);
        const alpha = 0.52 + 0.30 * shimmer + 0.12 * max * front;

        if (high > 0.04 && i % 4 === 1) {
          const tail = 2.0 + 2.5 * high + 3.1 * max;
          ctx.strokeStyle = `rgba(246, 205, 255, ${alpha * high * 0.40})`;
          ctx.lineWidth = 0.66;
          ctx.lineCap = "round";
          ctx.beginPath();
          ctx.moveTo(x - tail, y + 0.14);
          ctx.lineTo(x, y);
          ctx.stroke();
        }
        const size = 0.57 + i % 4 * 0.19 + 0.27 * max * front;
        if (i % 4 === 0 || (max > 0.04 && front > 0.65 && i % 2 === 0)) {
          const spread = size * (2.8 + 0.8 * max);
          ctx.save();
          ctx.globalAlpha *= 0.38 + 0.25 * shimmer;
          ctx.drawImage(glow, x - spread, y - spread, spread * 2, spread * 2);
          ctx.restore();
        }
        sceneDot(ctx, x, y, size, `rgba(255, 244, 255, ${alpha})`);
      }

      // 满档在游标下方抛出一小簇星尘，低档与高档持续巡航。
      if (burst > 0) {
        const age = 1 - burst;
        for (let i = 0; i < 7; i++) {
          const angle = i * 2.4;
          const x = end - 14 - age * (12 + i * 5);
          const y = 16 + Math.sin(angle) * (2.7 + age * 11.5);
          sceneDot(ctx, x, y, 0.68 + 0.45 * burst, `rgba(255, 238, 255, ${burst * 0.84})`);
        }
      }
    }

    function drawClaudeMosaic(ctx, end, time, high, max, burst) {
      const tile = 5.0;
      const columns = Math.ceil(end / tile);
      const sweep = (time * 7.1) % (columns + 7);
      const lead = Math.floor(sweep) + sceneEase(0.12, 0.72, sweep % 1);
      const rows = 1 + (high > 0.22 ? 2 : 0) + (max > 0.45 ? 2 : 0);
      const middle = Math.floor(rows / 2);
      for (let row = 0; row < rows; row++) {
        const y = 16 + (row - middle) * 5.4 - tile * 0.5;
        for (let column = 0; column < columns; column++) {
          const x = column * tile + 1.0;
          const hash = (column * 29 + row * 17) % 13;
          const front = sceneEase(0.15, 0.94, x / end);
          const phase = (lead - column - row * 1.45 + columns + 7) % (columns + 7);
          const wake = sceneEase(4.2 + high * 4.2, 0, phase);
          const paleTile = hash === 0 || hash === 5 || hash === 9;
          const nearEntry = Math.max(0, 1 - Math.abs(x - end * (0.92 - (1 - burst) * 0.70)) / (12 + max * 8));
          const alpha = (0.10 + 0.27 * front + 0.21 * high * front) * (0.70 + hash / 28)
            + wake * (0.32 + 0.11 * max) + burst * nearEntry * 0.33;
          ctx.fillStyle = paleTile
            ? `rgba(253, 244, 255, ${0.36 + alpha * 0.58})`
            : `rgba(85, 55, 158, ${Math.min(0.97, alpha)})`;
          const lift = wake * (0.35 + 0.45 * high);
          ctx.fillRect(x, y - lift, 3.85, 3.95 + lift * 0.7);
          if (max > 0.15 && front > 0.63 && hash % 4 === 0) {
            ctx.fillStyle = `rgba(255, 251, 255, ${(0.32 + 0.48 * wake) * max})`;
            ctx.fillRect(x + 0.5, y + 0.38, 2.1, 0.65);
          }
        }
      }
    }

    const gardenPlanting = [
      ["sky", 0.053, 19, 23],
      ["lilac", 0.13, 11, 20],
      ["sky", 0.18, 23, 15],
      ["spring", 0.30, 15.5, 23],
      ["lilac", 0.39, 24, 18],
      ["ivory", 0.50, 13.5, 27],
      ["peach", 0.62, 21, 25],
      ["sky", 0.70, 9, 15],
      ["ivory", 0.79, 19, 27],
      ["peach", 0.89, 12, 23],
      ["spring", 0.94, 25, 20]
    ];

    const sceneSprites = new Map();

    function getSoftGlowSprite(key, inner, mid, outer) {
      if (sceneSprites.has(key)) return sceneSprites.get(key);
      const sprite = document.createElement("canvas");
      sprite.width = sprite.height = 32;
      const gCtx = sprite.getContext("2d");
      const grad = gCtx.createRadialGradient(16, 16, 0, 16, 16, 16);
      grad.addColorStop(0, inner);
      grad.addColorStop(0.38, mid);
      grad.addColorStop(1, outer);
      gCtx.fillStyle = grad;
      gCtx.fillRect(0, 0, 32, 32);
      sceneSprites.set(key, sprite);
      return sprite;
    }

    function paintEllipseGlow(ctx, cx, cy, rx, ry, angle, stops) {
      ctx.save();
      ctx.translate(cx, cy);
      if (angle) ctx.rotate(angle);
      ctx.scale(rx / 32, ry / 32);
      const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, 32);
      stops.forEach(([at, color]) => grad.addColorStop(at, color));
      ctx.fillStyle = grad;
      ctx.fillRect(-32, -32, 64, 64);
      ctx.restore();
    }

    function buildSceneBackdrop(effect) {
      const canvas = document.createElement("canvas");
      canvas.width = 256;
      canvas.height = 32;
      const bCtx = canvas.getContext("2d");

      if (effect === "milky_way") {
        // 深空靛紫夜幕底色（参考银河实拍图）
        const sky = bCtx.createLinearGradient(0, 0, 256, 32);
        sky.addColorStop(0, "#070917");
        sky.addColorStop(0.28, "#0f122c");
        sky.addColorStop(0.56, "#171436");
        sky.addColorStop(0.82, "#10132c");
        sky.addColorStop(1, "#080b1b");
        bCtx.fillStyle = sky;
        bCtx.fillRect(0, 0, 256, 32);

        // 柔和斜贯全轨的银河星云带：冷蓝紫晕 -> 玫瑰薰衣草 -> 暖香槟银心
        paintEllipseGlow(bCtx, 42, 21, 64, 15, -0.14, [
          [0, "rgba(86, 118, 210, 0.36)"], [0.5, "rgba(74, 88, 178, 0.16)"], [1, "rgba(35, 42, 100, 0)"]
        ]);
        paintEllipseGlow(bCtx, 114, 16, 78, 15, -0.13, [
          [0, "rgba(154, 110, 206, 0.38)"], [0.46, "rgba(108, 94, 188, 0.22)"], [1, "rgba(44, 34, 96, 0)"]
        ]);
        paintEllipseGlow(bCtx, 168, 14, 66, 13, -0.12, [
          [0, "rgba(232, 168, 174, 0.38)"], [0.48, "rgba(166, 116, 186, 0.22)"], [1, "rgba(72, 48, 118, 0)"]
        ]);
        paintEllipseGlow(bCtx, 146, 16, 46, 9, -0.11, [
          [0, "rgba(255, 232, 208, 0.46)"], [0.45, "rgba(242, 192, 176, 0.22)"], [1, "rgba(200, 140, 160, 0)"]
        ]);
        paintEllipseGlow(bCtx, 224, 11, 52, 13, -0.14, [
          [0, "rgba(116, 136, 224, 0.34)"], [0.55, "rgba(92, 82, 176, 0.16)"], [1, "rgba(32, 30, 82, 0)"]
        ]);

        // 银河暗尘埃裂带（Dark Rift），还原星云深邃层次
        paintEllipseGlow(bCtx, 98, 15, 34, 4.4, -0.16, [
          [0, "rgba(10, 7, 22, 0.56)"], [0.65, "rgba(14, 10, 28, 0.24)"], [1, "rgba(14, 10, 28, 0)"]
        ]);
        paintEllipseGlow(bCtx, 166, 11.5, 38, 4.2, -0.12, [
          [0, "rgba(12, 8, 24, 0.52)"], [0.68, "rgba(16, 11, 30, 0.22)"], [1, "rgba(16, 11, 30, 0)"]
        ]);

        // 静态深空微尘背景星（保证 Low 档与减少动态效果下也有细腻星海）
        const dustTints = ["rgba(222, 236, 255,", "rgba(238, 224, 255,", "rgba(255, 238, 222,"];
        for (let i = 0; i < 96; i++) {
          const sx = (i * 53 + 17) % 256;
          const bandY = 22 - (sx / 256) * 12;
          const spread = ((i * 29) % 19 - 9) * (i % 3 === 0 ? 0.65 : 1.35);
          const sy = Math.max(1.5, Math.min(30.5, bandY + spread));
          const sr = 0.34 + (i % 4) * 0.12;
          const sa = (0.24 + (i % 5) * 0.11).toFixed(2);
          sceneDot(bCtx, sx, sy, sr, `${dustTints[i % 3]} ${sa})`);
        }
        return canvas;
      }

      if (effect === "crystal_ice") {
        // 提炼冰块参考图的冷白逆光、冰川天青与深钴蓝折射色域，把整条轨道雕琢为透光冰川水晶本体
        const base = bCtx.createLinearGradient(0, 0, 256, 32);
        base.addColorStop(0, "#103c70");
        base.addColorStop(0.22, "#1f64a4");
        base.addColorStop(0.50, "#4e9cd9");
        base.addColorStop(0.76, "#2c74b4");
        base.addColorStop(1, "#124278");
        bCtx.fillStyle = base;
        bCtx.fillRect(0, 0, 256, 32);

        // 垂直光学透射层：顶部清冽冷白透光 -> 中层冰川蓝 -> 底部沉静深钴蓝
        const depth = bCtx.createLinearGradient(0, 0, 0, 32);
        depth.addColorStop(0, "rgba(232, 247, 255, 0.76)");
        depth.addColorStop(0.26, "rgba(176, 224, 252, 0.42)");
        depth.addColorStop(0.58, "rgba(74, 152, 218, 0.14)");
        depth.addColorStop(1, "rgba(8, 34, 68, 0.56)");
        bCtx.fillStyle = depth;
        bCtx.fillRect(0, 0, 256, 32);

        // 冰体内部斜向背光折射柔晕（仿佛光线穿透整块透明冰体）
        paintEllipseGlow(bCtx, 44, 10, 68, 15, -0.22, [
          [0, "rgba(246, 252, 255, 0.72)"], [0.46, "rgba(176, 226, 254, 0.34)"], [1, "rgba(110, 186, 240, 0)"]
        ]);
        paintEllipseGlow(bCtx, 134, 16, 78, 16, -0.18, [
          [0, "rgba(238, 250, 255, 0.66)"], [0.44, "rgba(146, 212, 250, 0.32)"], [1, "rgba(70, 150, 218, 0)"]
        ]);
        paintEllipseGlow(bCtx, 218, 12, 66, 15, -0.20, [
          [0, "rgba(248, 253, 255, 0.74)"], [0.48, "rgba(168, 222, 252, 0.34)"], [1, "rgba(90, 170, 232, 0)"]
        ]);
        // 冰层深处的冷邃钴蓝暗影口袋，拉出通透冰晶的体积对比
        paintEllipseGlow(bCtx, 88, 26, 52, 10, 0.10, [
          [0, "rgba(10, 40, 82, 0.52)"], [0.65, "rgba(18, 62, 114, 0.22)"], [1, "rgba(18, 62, 114, 0)"]
        ]);
        paintEllipseGlow(bCtx, 186, 27, 56, 10, -0.08, [
          [0, "rgba(9, 36, 76, 0.50)"], [0.65, "rgba(16, 58, 110, 0.20)"], [1, "rgba(16, 58, 110, 0)"]
        ]);

        // 冰川内部天然纤细冰裂晶脉（柔和半透明，勾勒冰体内部折光层理）
        bCtx.save();
        bCtx.lineCap = "round";
        const veins = [
          [12, 26, 48, 14, 86, 4],
          [66, 30, 112, 17, 158, 6],
          [144, 28, 186, 15, 228, 3],
          [194, 30, 226, 19, 254, 11]
        ];
        veins.forEach(([x0, y0, cx, cy, x1, y1], idx) => {
          bCtx.strokeStyle = idx % 2 === 0 ? "rgba(232, 248, 255, 0.24)" : "rgba(196, 234, 255, 0.18)";
          bCtx.lineWidth = 2.2;
          bCtx.beginPath();
          bCtx.moveTo(x0, y0);
          bCtx.quadraticCurveTo(cx, cy, x1, y1);
          bCtx.stroke();

          bCtx.strokeStyle = "rgba(255, 255, 255, 0.42)";
          bCtx.lineWidth = 0.65;
          bCtx.stroke();
        });
        bCtx.restore();

        // 冰体中冻结的微距细密气泡链（赋予清澈透冰的真实肌理）
        for (let i = 0; i < 48; i++) {
          const bx = (i * 37 + 11) % 250 + 3;
          const by = 4 + (i * 19) % 24;
          const br = 0.35 + (i % 4) * 0.22;
          sceneDot(bCtx, bx, by + 0.14, br, "rgba(14, 52, 98, 0.26)");
          sceneDot(bCtx, bx, by, br * 0.85, "rgba(220, 244, 255, 0.38)");
          sceneDot(bCtx, bx - br * 0.28, by - br * 0.28, Math.max(0.18, br * 0.38), "rgba(255, 255, 255, 0.86)");
        }
        return canvas;
      }

      return canvas;
    }

    const milkyHeroStars = [
      [0.14, 19.5, 1.05, "cool"],
      [0.34, 15.0, 1.15, "warm"],
      [0.57, 13.8, 1.35, "warm"],
      [0.72, 10.6, 1.48, "cool"],
      [0.89, 12.4, 1.18, "violet"]
    ];

    function drawMilkyWay(ctx, width, end, time, high, max, burst) {
      const coolGlow = getSoftGlowSprite("mw_cool", "rgba(235, 246, 255, 0.90)", "rgba(152, 194, 255, 0.32)", "rgba(104, 142, 232, 0)");
      const warmGlow = getSoftGlowSprite("mw_warm", "rgba(255, 245, 232, 0.92)", "rgba(246, 196, 164, 0.34)", "rgba(206, 132, 154, 0)");
      const violetGlow = getSoftGlowSprite("mw_violet", "rgba(246, 236, 255, 0.88)", "rgba(182, 144, 246, 0.30)", "rgba(120, 88, 204, 0)");
      const glows = [coolGlow, warmGlow, violetGlow];

      // 银心柔光呼吸（随 High / Max 柔和增强）
      if (high > 0.04 || max > 0.04) {
        const pulse = 0.84 + 0.16 * Math.sin(time * 0.95);
        ctx.save();
        ctx.globalAlpha *= (0.14 * high + 0.22 * max) * pulse;
        ctx.drawImage(warmGlow, width * 0.36, 2, width * 0.42, 26);
        ctx.restore();
      }

      // 动态多层景深星群：沿银河带自然聚散，轻柔呼吸不刺眼
      const count = Math.round(16 + 12 * high + 14 * max);
      const span = Math.max(end + 10, 48);
      for (let i = 0; i < count; i++) {
        const speed = 1.6 + (i % 5) * 0.65 + max * 0.9;
        const x = (((i * 83) % 197) / 197 * span + time * speed) % span - 4;
        const bandY = 22 - (x / Math.max(width, 64)) * 12;
        const offset = ((i * 31) % 21 - 10) * (i % 3 === 0 ? 0.58 : 1.18);
        const y = Math.max(2.2, Math.min(29.8, bandY + offset + Math.sin(time * 0.65 + i * 1.9) * 0.35));
        const twinkle = 0.52 + 0.48 * Math.sin(time * (0.95 + (i % 4) * 0.28) + i * 2.37);
        const radius = 0.42 + (i % 4) * 0.17 + (i % 5 === 0 ? 0.22 * max : 0);
        const alpha = (0.42 + 0.48 * twinkle) * (0.82 + 0.18 * max);
        if (i % 4 === 0) {
          const halo = radius * (3.6 + 1.1 * max);
          ctx.save();
          ctx.globalAlpha *= (0.28 + 0.32 * twinkle);
          ctx.drawImage(glows[i % 3], x - halo, y - halo, halo * 2, halo * 2);
          ctx.restore();
        }
        const dotColor = i % 3 === 0 ? `rgba(222, 238, 255, ${alpha})`
          : i % 3 === 1 ? `rgba(255, 240, 224, ${alpha})` : `rgba(242, 230, 255, ${alpha})`;
        sceneDot(ctx, x, y, radius, dotColor);
      }

      // 标志性亮星与柔和十字星芒（呼应参考图右上的冰蓝亮星）
      for (let i = 0; i < milkyHeroStars.length; i++) {
        const [px, py, size, tone] = milkyHeroStars[i];
        const x = width * px;
        if (x > end + 6) continue;
        const breath = 0.72 + 0.28 * Math.sin(time * 1.15 + i * 1.85);
        const sprite = tone === "cool" ? coolGlow : tone === "warm" ? warmGlow : violetGlow;
        const halo = size * (4.2 + 1.2 * high + 1.4 * max) * (0.92 + 0.12 * breath);
        ctx.save();
        ctx.globalAlpha *= (0.52 + 0.28 * high + 0.20 * max) * breath;
        ctx.drawImage(sprite, x - halo, py - halo, halo * 2, halo * 2);
        ctx.restore();

        const spikeLen = size * (2.2 + 2.2 * high + 2.6 * max) * breath;
        if (spikeLen > 2.4) {
          ctx.save();
          ctx.strokeStyle = tone === "cool" ? `rgba(226, 242, 255, ${(0.38 + 0.34 * max) * breath})`
            : `rgba(255, 242, 226, ${(0.36 + 0.32 * max) * breath})`;
          ctx.lineWidth = 0.58;
          ctx.lineCap = "round";
          ctx.beginPath();
          ctx.moveTo(x - spikeLen, py);
          ctx.lineTo(x + spikeLen, py);
          ctx.moveTo(x, py - spikeLen * 0.82);
          ctx.lineTo(x, py + spikeLen * 0.82);
          ctx.stroke();
          ctx.restore();
        }
        sceneDot(ctx, x, py, size * 0.72, "rgba(255, 253, 255, 0.96)");
      }

      // High / Max：偶发柔和流星轻掠夜空
      if (high > 0.15) {
        const cycle = (time * 0.34) % 1;
        if (cycle < 0.28) {
          const p = cycle / 0.28;
          const fade = Math.sin(p * Math.PI) * (0.45 * high + 0.40 * max);
          const mx = end * (0.28 + p * 0.58);
          const my = 5 + p * 14;
          const tail = 9 + 7 * max;
          ctx.save();
          ctx.strokeStyle = `rgba(236, 244, 255, ${fade})`;
          ctx.lineWidth = 0.78;
          ctx.lineCap = "round";
          ctx.beginPath();
          ctx.moveTo(mx - tail, my - tail * 0.32);
          ctx.lineTo(mx, my);
          ctx.stroke();
          sceneDot(ctx, mx, my, 0.85, `rgba(255, 255, 255, ${Math.min(1, fade * 1.4)})`);
          ctx.restore();
        }
      }

      if (burst > 0) {
        const age = 1 - burst;
        for (let i = 0; i < 8; i++) {
          const a = i * 2.39;
          const x = end - 12 - age * (10 + i * 5.2);
          const y = 16 + Math.sin(a) * (2.5 + age * 11.5);
          sceneDot(ctx, x, y, 0.65 + 0.55 * burst, i % 2 === 0
            ? `rgba(224, 242, 255, ${burst * 0.88})`
            : `rgba(255, 234, 206, ${burst * 0.86})`);
        }
      }
    }

    function getIceRefractPlaneSprite() {
      const key = "ice_refract_plane";
      if (sceneSprites.has(key)) return sceneSprites.get(key);
      const sprite = document.createElement("canvas");
      sprite.width = 72;
      sprite.height = 36;
      const rCtx = sprite.getContext("2d");
      // 柔和的斜向冰晶折光切面：清透白青亮脊向两侧自然羽化，零生硬边线
      rCtx.save();
      rCtx.transform(1, 0, -0.58, 1, 22, 0);
      const grad = rCtx.createLinearGradient(0, 0, 56, 0);
      grad.addColorStop(0, "rgba(188, 232, 255, 0)");
      grad.addColorStop(0.28, "rgba(198, 238, 255, 0.26)");
      grad.addColorStop(0.47, "rgba(255, 255, 255, 0.64)");
      grad.addColorStop(0.56, "rgba(220, 246, 255, 0.34)");
      grad.addColorStop(0.82, "rgba(130, 204, 248, 0.14)");
      grad.addColorStop(1, "rgba(130, 204, 248, 0)");
      rCtx.fillStyle = grad;
      rCtx.fillRect(0, 0, 56, 36);
      rCtx.restore();
      sceneSprites.set(key, sprite);
      return sprite;
    }

    function getFrostCrystalSprite(variant) {
      const key = `frost_crystal_${variant}`;
      if (sceneSprites.has(key)) return sceneSprites.get(key);
      const sprite = document.createElement("canvas");
      sprite.width = sprite.height = 64;
      const c = sprite.getContext("2d");
      c.translate(32, 32);

      // 柔和的冰晶背景寒晕
      const halo = c.createRadialGradient(0, 0, 0, 0, 0, 29);
      halo.addColorStop(0, "rgba(255, 255, 255, 0.66)");
      halo.addColorStop(0.42, "rgba(196, 236, 255, 0.28)");
      halo.addColorStop(1, "rgba(140, 208, 248, 0)");
      c.fillStyle = halo;
      c.fillRect(-32, -32, 64, 64);

      // 六重对称枝状霜花晶核（两套精致形态：纤雅羽枝 / 冰棱星片）
      c.strokeStyle = "rgba(248, 253, 255, 0.90)";
      c.lineCap = "round";
      const armLen = variant === 0 ? 23 : 20;
      for (let i = 0; i < 6; i++) {
        c.save();
        c.rotate((i * Math.PI) / 3);
        c.lineWidth = variant === 0 ? 1.35 : 1.65;
        c.beginPath();
        c.moveTo(0, 0);
        c.lineTo(0, -armLen);
        c.stroke();

        // 晶枝分叉（60° 天然冰晶结晶角）
        c.lineWidth = 1.05;
        const forks = variant === 0 ? [[9, 6.2], [15.5, 5.2], [20, 2.8]] : [[8, 5.5], [14.5, 4.6]];
        forks.forEach(([y, len]) => {
          c.beginPath();
          c.moveTo(0, -y);
          c.lineTo(-len * 0.86, -y - len * 0.5);
          c.moveTo(0, -y);
          c.lineTo(len * 0.86, -y - len * 0.5);
          c.stroke();
        });
        c.restore();
      }

      // 中心透明六角冰核
      c.beginPath();
      for (let i = 0; i < 6; i++) {
        const a = (i * Math.PI) / 3;
        const px = Math.cos(a) * 5.2;
        const py = Math.sin(a) * 5.2;
        if (i === 0) c.moveTo(px, py);
        else c.lineTo(px, py);
      }
      c.closePath();
      c.fillStyle = "rgba(232, 248, 255, 0.72)";
      c.fill();
      c.strokeStyle = "rgba(255, 255, 255, 0.92)";
      c.lineWidth = 0.9;
      c.stroke();

      sceneSprites.set(key, sprite);
      return sprite;
    }

    const frostBloomNodes = [
      [0.11, 14.5, 16, 0, 0.18],
      [0.27, 20.5, 13, 1, -0.22],
      [0.44, 12.2, 18, 0, 0.14],
      [0.60, 19.6, 15, 1, -0.16],
      [0.75, 13.4, 19, 0, 0.20],
      [0.89, 18.4, 16, 1, -0.15]
    ];

    function drawCrystalIce(ctx, width, end, time, high, max, burst) {
      const refractPlane = getIceRefractPlaneSprite();
      const frostGlow = getSoftGlowSprite("ice_frost", "rgba(255, 255, 255, 0.88)", "rgba(194, 236, 255, 0.40)", "rgba(130, 204, 248, 0)");
      const causticGlow = getSoftGlowSprite("ice_caustic", "rgba(232, 250, 255, 0.82)", "rgba(128, 204, 248, 0.34)", "rgba(38, 110, 182, 0)");

      // 1. 冰体内部缓慢滑行的斜向折光切面（核心视觉：像光线流转穿透整块透明冰川水晶）
      const planeCount = 4 + Math.round(2 * high + 2 * max);
      const span = Math.max(width + 72, 180);
      for (let i = 0; i < planeCount; i++) {
        const speed = 4.2 + (i % 3) * 1.9 + max * 2.2;
        const px = ((i * 59 + time * speed) % span) - 48;
        if (px - 10 > end) continue;
        const pw = 36 + (i % 4) * 14;
        const breath = 0.64 + 0.36 * Math.sin(time * (0.75 + (i % 3) * 0.2) + i * 2.1);
        ctx.save();
        ctx.globalAlpha *= (0.24 + 0.20 * high + 0.22 * max) * breath;
        ctx.drawImage(refractPlane, px, -2, pw, 36);
        ctx.restore();
      }

      // 2. 冰下冷润焦散波纹（低频呼吸起伏）
      const causticCount = 5 + Math.round(2 * high + 2 * max);
      for (let i = 0; i < causticCount; i++) {
        const cx = (((i * 67 + 13) % 193) / 193 * span + time * (2.6 + (i % 3) * 0.8)) % span - 24;
        if (cx - 28 > end) continue;
        const pulse = 0.65 + 0.35 * Math.sin(time * (0.85 + (i % 3) * 0.18) + i * 1.9);
        ctx.save();
        ctx.globalAlpha *= (0.22 + 0.18 * high + 0.20 * max) * pulse;
        ctx.drawImage(causticGlow, cx - 26, 19, 52, 15);
        ctx.restore();
      }

      // 3. 悄然凝结与缓旋的六瓣霜花晶华（Low 极淡远景微晶，High / Max 逐层清透绽放）
      for (let i = 0; i < frostBloomNodes.length; i++) {
        const [px, baseY, baseSize, variant, spinSpeed] = frostBloomNodes[i];
        const x = width * px + Math.sin(time * 0.42 + i * 1.8) * 1.2;
        if (x - baseSize * 0.6 > end) continue;
        const reveal = sceneEase(0, 18, end - x + 6);
        const tierVis = i % 2 === 0 ? (0.34 + 0.42 * high + 0.24 * max) : (0.14 + 0.48 * high + 0.38 * max);
        const breath = 0.78 + 0.22 * Math.sin(time * (0.85 + (i % 3) * 0.16) + i * 2.4);
        const size = baseSize * (0.84 + 0.16 * high + 0.18 * max) * (0.94 + 0.06 * breath);
        const y = baseY + Math.sin(time * 0.6 + i * 2.1) * 0.8;
        const sprite = getFrostCrystalSprite(variant);

        ctx.save();
        ctx.globalAlpha *= reveal * tierVis * breath;
        ctx.translate(x, y);
        ctx.rotate(time * spinSpeed + i * 0.9);
        ctx.drawImage(sprite, -size * 0.5, -size * 0.5, size, size);
        ctx.restore();
      }

      // 4. High / Max：贴近冰面轻缓漫过的清冽霜雾
      if (high > 0.06) {
        const mistCount = 4 + Math.round(3 * max);
        for (let m = 0; m < mistCount; m++) {
          const mx = ((m * 72 + time * (4.2 + m * 0.8)) % (span + 20)) - 30;
          if (mx - 32 > end) continue;
          const my = 7 + (m % 3) * 8 + Math.sin(time * 0.52 + m * 1.7) * 1.4;
          ctx.save();
          ctx.globalAlpha *= (0.15 * high + 0.16 * max);
          ctx.drawImage(frostGlow, mx - 30, my - 7, 60, 14);
          ctx.restore();
        }
      }

      // 5. 晶莹冷凝微露珠与悬浮钻石冰尘（微距冷润质感，无杂乱感）
      const beadCount = Math.round(12 + 10 * high + 12 * max);
      for (let i = 0; i < beadCount; i++) {
        const bx = (((i * 43 + 7) % 179) / 179 * Math.max(width, 96) + (i % 4 === 0 ? time * 1.8 : 0)) % Math.max(width, 96);
        if (bx > end - 1) continue;
        const by = 4 + (i * 17) % 24 + Math.sin(time * 0.8 + i) * 0.5;
        const r = 0.45 + (i % 3) * 0.26;
        if (i % 4 === 0 && (high > 0.15 || max > 0.05)) {
          // 钻石冰尘四芒微闪（< 1.3Hz）
          const spark = Math.max(0, Math.sin(time * (1.1 + (i % 3) * 0.2) + i * 2.5)) ** 6;
          if (spark > 0.12) {
            const s = spark * (0.45 * high + 0.55 * max);
            const arm = 2.0 + 2.6 * s;
            ctx.save();
            ctx.strokeStyle = `rgba(255, 255, 255, ${(0.88 * s).toFixed(3)})`;
            ctx.lineWidth = 0.58;
            ctx.lineCap = "round";
            ctx.beginPath();
            ctx.moveTo(bx - arm, by);
            ctx.lineTo(bx + arm, by);
            ctx.moveTo(bx, by - arm * 0.85);
            ctx.lineTo(bx, by + arm * 0.85);
            ctx.stroke();
            ctx.restore();
          }
        }
        sceneDot(ctx, bx, by + 0.18, r, "rgba(10, 42, 86, 0.34)");
        sceneDot(ctx, bx, by, r * 0.86, "rgba(210, 242, 255, 0.46)");
        sceneDot(ctx, bx - r * 0.28, by - r * 0.28, Math.max(0.22, r * 0.40), "rgba(255, 255, 255, 0.94)");
      }

      // 6. 顶部极细的湿润玻璃冰缘高光丝线，统一整条水晶的通透完成度
      ctx.save();
      ctx.fillStyle = "rgba(246, 253, 255, 0.36)";
      ctx.fillRect(0, 1.2, end, 0.9);
      ctx.restore();

      // 7. Max 入档：瞬冻霜华波纹与钻石冰尘向内绽放
      if (burst > 0) {
        const age = 1 - burst;
        const r = 10 + age * 28;
        ctx.save();
        ctx.globalAlpha *= burst * 0.72;
        ctx.drawImage(frostGlow, end - 10 - r, 16 - r, r * 2, r * 2);
        const crystal = getFrostCrystalSprite(0);
        const cs = 12 + age * 18;
        ctx.translate(end - 12 - age * 8, 16);
        ctx.rotate(age * 0.9);
        ctx.drawImage(crystal, -cs * 0.5, -cs * 0.5, cs, cs);
        ctx.restore();
        for (let i = 0; i < 10; i++) {
          const a = i * 2.35;
          const x = end - 10 - age * (14 + (i % 4) * 7);
          const y = 16 + Math.sin(a) * (2.5 + age * 11.5);
          sceneDot(ctx, x, y, 0.60 + 0.55 * burst, i % 2 === 0
            ? `rgba(255, 255, 255, ${burst * 0.95})`
            : `rgba(176, 230, 255, ${burst * 0.88})`);
        }
      }
    }

    function drawSliderScene(ctx, effect, width, end, height, time, high, max, pal, dark, brightness, mercuryTilt, burstT = 0) {
      if (height <= 0 || width <= 0 || end <= 0) return;
      const scale = height / 32;
      const sceneWidth = width / scale;
      const sceneEnd = end / scale;
      const burst = Math.min(1, Math.max(0, burstT));
      const key = effect === "liquid_mercury" ? `${effect}:${scale}:${dark}:${pal.hex}:${brightness}` : `${effect}:${scale}`;

      ctx.save();
      ctx.scale(scale, scale);
      ctx.beginPath();
      ctx.rect(0, 0, sceneEnd, 32);
      ctx.clip();
      ctx.globalCompositeOperation = "source-over";
      ctx.globalAlpha = Math.min(1, 0.38 + brightness * 0.58);
      let cached = sceneGradients.get(ctx);
      if (cached?.key !== key) {
        const stops = sceneSkies[effect] || [
          [0, dark ? "#a2c5d3" : "#d8edf0"], [0.17, "#dcebf1"], [0.38, "#668899"],
          [0.49, "#2f4b5a"], [0.55, "#b2d8df"], [0.72, pal.deep(0.88)],
          [0.94, "#587e92"], [1, "#afcbd5"]
        ];
        if (effect === "liquid_mercury") {
          // 将光带缓存成纹理，让整条渐变跟随弹簧剪切。上下各预留 8px。
          const strip = document.createElement("canvas");
          strip.width = 1;
          strip.height = 96;
          const stripCtx = strip.getContext("2d");
          const gradient = stripCtx.createLinearGradient(0, 16, 0, 80);
          stops.forEach(([at, color]) => gradient.addColorStop(at, color));
          stripCtx.fillStyle = gradient;
          stripCtx.fillRect(0, 0, strip.width, strip.height);
          cached = { key, strip };
        } else if (effect === "gpt_starlight") {
          // 预绘横向色带，拖动时只缩放到当前有效宽度。
          const ramp = document.createElement("canvas");
          ramp.width = 256;
          ramp.height = 1;
          const rampCtx = ramp.getContext("2d");
          const gradient = rampCtx.createLinearGradient(0, 0, ramp.width, 0);
          stops.forEach(([at, color]) => gradient.addColorStop(at, color));
          rampCtx.fillStyle = gradient;
          rampCtx.fillRect(0, 0, ramp.width, 1);
          cached = { key, ramp };
        } else if (effect === "milky_way" || effect === "crystal_ice") {
          cached = { key, backdrop: buildSceneBackdrop(effect) };
        } else {
          const base = ctx.createLinearGradient(0, 0, 0, 32);
          stops.forEach(([at, color]) => base.addColorStop(at, color));
          cached = { key, base };
        }
        sceneGradients.set(ctx, cached);
      }
      if (cached.strip) {
        const slope = mercuryTilt / Math.max(sceneEnd, 32);
        const edgeShift = slope * sceneEnd * 0.5;
        ctx.save();
        ctx.transform(1, slope, 0, 1, 0, -edgeShift);
        ctx.drawImage(cached.strip, 0, -8, sceneEnd, 48);
        ctx.restore();
      } else if (cached.ramp) {
        ctx.drawImage(cached.ramp, 0, 0, sceneEnd, 32);
      } else if (cached.backdrop) {
        ctx.drawImage(cached.backdrop, 0, 0, sceneWidth, 32);
      } else {
        ctx.fillStyle = cached.base;
        ctx.fillRect(0, 0, sceneEnd, 32);
      }

      switch (effect) {
        case "gpt_starlight":
          drawGptStarlight(ctx, sceneEnd, time, high, max, burst);
          break;
        case "claude_mosaic":
          drawClaudeMosaic(ctx, sceneEnd, time, high, max, burst);
          break;
        case "milky_way":
          drawMilkyWay(ctx, sceneWidth, sceneEnd, time, high, max, burst);
          break;
        case "crystal_ice":
          drawCrystalIce(ctx, sceneWidth, sceneEnd, time, high, max, burst);
          break;
        default:
          drawGlassMercury(ctx, sceneEnd, time, high, max, pal, mercuryTilt);
      }
      ctx.restore();
    }

    function drawSliderSceneTransition(ctx, width, end, height, burst, afterglow, pal, dark) {
      if (burst <= 0 && afterglow <= 0) return;
      ctx.save();
      ctx.globalCompositeOperation = "source-over";
      if (burst > 0) {
        ctx.beginPath();
        const radius = Math.max(0, 1 - burst) * width * 0.85;
        ctx.arc(end, height / 2, radius, 0, Math.PI * 2);
        ctx.strokeStyle = dark ? `rgba(239, 248, 255, ${burst * 0.48})` : pal.main(burst * 0.5);
        ctx.lineWidth = height * 0.068 * burst;
        ctx.stroke();
        ctx.fillStyle = `rgba(241, 248, 255, ${burst * 0.09})`;
        ctx.fillRect(0, 0, end, height);
      }
      if (afterglow > 0) {
        ctx.fillStyle = pal.light(afterglow * 0.12);
        ctx.fillRect(0, 0, end, height);
      }
      ctx.restore();
    }

