      const isDraggingRef = useRef(false);
      const gestureRef = useRef(null);
      const glintSpotRef = useRef(null);
      const glintRef = useRef({ element: null, rect: null, x: 0, y: 0, dirty: false, reduced: false });
      const lastActionRef = useRef(effortAction);
      const lastCommitPulseRef = useRef(-Infinity);
