          if (rect.width <= 0) return;
          const x = (event.clientX - rect.left) * track.offsetWidth / rect.width - track.clientLeft;
          const ratio = Math.max(0, Math.min(1, (x - 14) / (width - 28)));
          line.style.transform = `translate3d(${Math.max(0, Math.min(width, x))}px, 0, 0)`;
          line.classList.add("is-visible");
