              h("circle", { className: "dcs-tune-knob-top", cx: 6, cy: 4.5, r: 1.6, fill: "currentColor", stroke: "none" }),
              h("line", { x1: 2.5, y1: 11.5, x2: 13.5, y2: 11.5 }),
              h("circle", { className: "dcs-tune-knob-bot", cx: 10.5, cy: 11.5, r: 1.6, fill: "currentColor", stroke: "none" })
